{
  "title": "The Glass Diver's Rescue",
  "gate_token": "_9_67-e9SNlRWSpS3cabPg",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party approaches the ruined city.",
      "visual_description": "Crumbled walls, broken spires, and faded royal banners flutter in the wind. Mara studies a tattered map while the glass diver adjusts his helmet.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of a curse ahead.",
      "visual_description": "The lamp's single eye flickers as it speaks, casting long shadows across the rubble. Tin fox crouches alertly beside it.",
      "characters": ["oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The sleeping tax collector blocks a narrow alley.",
      "visual_description": "He snores loudly, using a ledger as a pillow, with stamped papers stuck to his sleeves, sprawled across the only path forward.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 4,
      "caption": "Mara finds a hidden route on her map.",
      "visual_description": "She traces an ink line with a compass, revealing a forgotten passage through a collapsed tower. Glass diver peers over her shoulder.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The party enters the castle gate.",
      "visual_description": "Massive iron gates stand ajar, rusted and creaking. Inside, a courtyard is littered with broken statues and faded banners.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The oracle lamp reveals a magical door.",
      "visual_description": "A door glows with runes that shift as the lamp's light touches them, pulsing with an unknown spell.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The glass diver swims through the door's reflection.",
      "visual_description": "He presses his helmet against a cracked mirror nearby, then steps through into the room beyond, his coat reflecting the city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Inside, they find a cursed tower.",
      "visual_description": "The tower spirals upward, walls covered in shifting shadows. A single window shows a false sky. Tin fox's gears whir nervously.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The oracle lamp whispers rumors of a great beast.",
      "visual_description": "The lamp's flame dims as it speaks of a winged shadow that circles the tower at dusk. Mara marks a warning on her map.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The sleeping tax collector is carried to safety.",
      "visual_description": "Tin fox nudges him awake, but he only mumbles and rolls over. The glass diver hoists him onto his shoulders, helmet fogging.",
      "characters": ["glass_diver", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Armored patrols march through the main square.",
      "visual_description": "Figures in gleaming plate armor move in unison, their visors down, scanning the ruins. The party hides behind a collapsed market stall.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "Mara deciphers a clue from the old royal banners.",
      "visual_description": "She reads the faded sigil on a fallen banner, cross-referencing it with her compass to find a secret stairwell.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The glass diver scouts ahead through a window.",
      "visual_description": "He presses his helmet to the glass, then steps through into a dark corridor, his body rippling like water.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The party reunites at a magic door.",
      "visual_description": "Three identical doors float in a circular room, each humming with a different tone. Oracle lamp's eye rotates to study them.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The sleeping tax collector sleepwalks through the correct door.",
      "visual_description": "He stumbles forward, muttering about ledgers, and pushes open the leftmost door, which clicks open with a welcome light.",
      "characters": ["sleeping_tax_collector", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "They reach the final bridge over a chasm.",
      "visual_description": "A narrow stone bridge spans a bottomless crack in the earth. The far side glows with escape. Faded banners line the bridge's edge.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge begins to crumble as they cross.",
      "visual_description": "Stones fall away behind them. Tin fox's tail winds furiously as it runs ahead. The glass diver grabs Mara's arm to steady her.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "They escape the city as dawn breaks.",
      "visual_description": "The party stands on a hillside, the ruined city below. The glass diver removes his helmet, and the oracle lamp's eye closes in rest.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "sleeping_tax_collector", "oracle_lamp"]
    }
  ]
}

